const user = { name: "Jan", age: 30 };
user.age = 31; // OK - modyfikujemy wlasciwosc, nie zmienna
console.log(user); // { name: 'Jan', age: 31 }

const tags = ["js", "node"];
tags.push("react"); // OK - metoda tablicowa modyfikuje ISTNIEJACA tablice
console.log(tags); // ['js', 'node', 'react']

const USTAWIENIA = { motywCiemny: true, jezyk: "pl" };

function zresetujMotyw(ustawienia) {
  ustawienia.motywCiemny = false; // CICHA modyfikacja - const NIE chroni przed tym
}

zresetujMotyw(USTAWIENIA);
console.log(USTAWIENIA.motywCiemny); // false - mimo ze USTAWIENIA to const!
// BLEDNE zalozenie: const NIE gwarantuje, ze obiekt pozostanie niezmieniony

const USTAWIENIA = Object.freeze({ motywCiemny: true, jezyk: "pl" });

function zresetujMotyw(ustawienia) {
  ustawienia.motywCiemny = false; // NIE dziala - obiekt jest zamrozony
}

zresetujMotyw(USTAWIENIA);
console.log(USTAWIENIA.motywCiemny); // true - nadal niezmienione

exercises.solution:
const PI = 3.14;
console.log(PI); // 3.14
// PI = 3.14159; // TypeError: Assignment to constant variable.
// blad pojawilby sie W MOMENCIE proby wykonania tej linii,
// przerywajac dalsze dzialanie skryptu w tym miejscu

const samochod = { marka: "Toyota", kolor: "czerwony" };
samochod.kolor = "niebieski";
console.log(samochod); // { marka: 'Toyota', kolor: 'niebieski' }

// const przechowuje ADRES (referencje) obiektu/tablicy w pamieci, nie sama
// wartosc bezposrednio. Metody typu push()/pop() oraz modyfikacja wlasciwosci
// (obiekt.pole = ...) DZIALAJA POD TYM ADRESEM - modyfikuja to, na co adres
// wskazuje, ale sam adres (zawartosc zmiennej const) pozostaje niezmieniony.
// Przypisanie nowej wartosci do calej zmiennej (np. tablica = []) probowaloby
// PODMIENIC ten adres na inny - a wlasnie tego const zabrania.

const LANGUAGES = ["JavaScript", "Java", "Python"];
LANGUAGES.push("TypeScript");
console.log(LANGUAGES); // ['JavaScript', 'Java', 'Python', 'TypeScript']
// mozna, bo push() modyfikuje ZAWARTOSC istniejacej tablicy,
// nie probuje podmienic calej zmiennej LANGUAGES na inna tablice

const config = { debug: false, maxRetries: 3 };
config.debug = true;
console.log(config); // { debug: true, maxRetries: 3 }

try {
  config = {};
} catch (e) {
  console.log(e.name); // "TypeError"
}

const numery = [1, 2, 3];

try {
  numery = [4, 5, 6];
} catch (e) {
  console.log(e.name); // "TypeError"
}

numery.length = 0;
numery.push(4, 5, 6);
console.log(numery); // [4, 5, 6]

function obliczPoleProstokata(szerokosc, wysokosc) {
  const pole = szerokosc * wysokosc;
  return pole;
}

console.log(obliczPoleProstokata(5, 3)); // 15

const osoba = {
  imie: "Ala",
  adres: { miasto: "Krakow", kodPocztowy: "30-001" }
};

osoba.adres.miasto = "Wroclaw";
console.log(osoba);
// { imie: 'Ala', adres: { miasto: 'Wroclaw', kodPocztowy: '30-001' } }

const osoba = {
  imie: "Ala",
  adres: { miasto: "Krakow", kodPocztowy: "30-001" }
};

osoba.adres = { miasto: "Gdansk", kodPocztowy: "80-001" };
console.log(osoba);
// { imie: 'Ala', adres: { miasto: 'Gdansk', kodPocztowy: '80-001' } }
// dozwolone, bo 'osoba.adres = ...' modyfikuje WLASCIWOSC istniejacego
// obiektu osoba - sama zmienna osoba WCIAZ wskazuje na TEN SAM obiekt

const koszyk = [];

function dodajDoKoszyka(produkt) {
  koszyk.push(produkt);
}

dodajDoKoszyka("chleb");
dodajDoKoszyka("maslo");
dodajDoKoszyka("ser");

console.log(koszyk); // ['chleb', 'maslo', 'ser']

const licznikOdwiedzin = { wartosc: 0 };

function odwiedz() {
  licznikOdwiedzin.wartosc = licznikOdwiedzin.wartosc + 1;
  console.log(licznikOdwiedzin.wartosc);
}

odwiedz(); // 1
odwiedz(); // 2
odwiedz(); // 3

const uzytkownicy = [
  { id: 1, aktywny: true },
  { id: 2, aktywny: true }
];

function wylaczUzytkownika(lista, id) {
  for (let i = 0; i < lista.length; i++) {
    if (lista[i].id === id) {
      lista[i].aktywny = false;
    }
  }
}

wylaczUzytkownika(uzytkownicy, 2);
console.log(uzytkownicy);
// [{ id: 1, aktywny: true }, { id: 2, aktywny: false }]

const identyfikator = "user_42"; // nigdy sie nie zmienia - const
let liczbaOdwiedzin = 0;         // bedzie zwiekszana - let
let ostatniaAktywnosc = Date.now(); // bedzie aktualizowana - let
// identyfikator to const, bo raz nadany identyfikator uzytkownika
// nigdy nie powinien zostac PODMIENIONY na inny w trakcie dzialania programu

const PRODUKTY = Object.freeze({ nazwa: "Laptop", cena: 3000 });
PRODUKTY.cena = 2000; // po cichu ignorowane
console.log(PRODUKTY.cena); // 3000 - NIEZMIENIONE
// Object.freeze() blokuje rowniez modyfikacje ZAWARTOSCI obiektu,
// nie tylko podmiane calej zmiennej - to prawdziwa ochrona,
// ktorej sam const nie daje
